"use client";

import { useRef, useState } from "react";
import { PromptBox } from "@/components/kit/base/variants/textarea-aui-008";

const models = [
  { id: "swift", label: "Swift", detail: "Fast answers for everyday tasks" },
  { id: "atlas", label: "Atlas", detail: "Deeper reasoning, a little slower" },
  { id: "mini", label: "Mini", detail: "Lowest cost" },
];

export default function Demo() {
  const [busy, setBusy] = useState(false);
  const [last, setLast] = useState<string | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  return (
    <div className="flex min-h-[420px] w-full items-center justify-center p-6 sm:p-10">
      <div className="w-full max-w-lg">
        <p className="mb-3 h-5 text-[13px] text-mute" aria-live="polite">
          {busy ? "Generating…" : last ? `Done with ${last}.` : "Pick a model, type, press Enter."}
        </p>
        <PromptBox
          models={models}
          busy={busy}
          onSubmit={({ model }) => {
            setBusy(true);
            timer.current = setTimeout(() => {
              setBusy(false);
              setLast(models.find((m) => m.id === model)?.label ?? model);
            }, 2400);
          }}
          onStop={() => {
            clearTimeout(timer.current);
            setBusy(false);
            setLast(null);
          }}
        />
      </div>
    </div>
  );
}
